{"command": "cd /workspace && python3 - <<'EOF'
import re, os
mods=set()
for line in open('yt_dlp/extractor/_extractors.py'):
    m=re.match(r'from \.(\w+) import', line.strip())
    if m: mods.add(m.group(1))
missing=[m for m in sorted(mods) if not os.path.exists(f'yt_dlp/extractor/{m}.py')]
print("missing:", missing)
print("total modules:", len(mods))
EOF"}

